window.kbPageData["views/entry/k-47bdde1e2a61faad"] = {"key":"entry/k-47bdde1e2a61faad","state":{"route":"entry/k-47bdde1e2a61faad"},"node":{"id":"k-47bdde1e2a61faad","mode":"k","title":"长征十号乙运载火箭全球首次网系回收成功（7 月 10 日）","type":"事实与事件","domain":"科技","reading":"","intro":"","priority":100,"aliases":[],"qs":[],"current":false,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":true,"tags":{"专题":["innovation"],"主类":["事实与事件"],"出处性质":["时政汇编"],"学科":["科技"],"时间索引":["年度事件或数据"],"来源主题":["重要科技成就"],"资料类别":["时政"]},"eventTags":[{"year":2026,"title":"长征十号乙运载火箭全球首次网系回收成功（7 月 10 日）","slug":"83f9b6c10c5d"}],"directorySummary":"考点八 长征十号乙运载火箭全球首次网系回收成功（7 月 10 日）\n2026 年 7 月 10 日 12 时 15 分，长征十号乙运载火箭在海南商业航天发射场发射升空，将卫星\n顺利送入预定轨道；火箭一二级分离约 6 分钟后，一子级垂直返回，在海上“领航者号”回收\n船上通过网系捕获方式成功回收。此次任…","sources":[{"id":"44eeb0150d7f9d8c","label":"长征十号乙运载火箭全球首次网系回收成功（7 月 10 日）","topic":"重要科技成就","category":"时政","text":"考点八 长征十号乙运载火箭全球首次网系回收成功（7 月 10 日）\n2026 年 7 月 10 日 12 时 15 分，长征十号乙运载火箭在海南商业航天发射场发射升空，将卫星\n顺利送入预定轨道；火箭一二级分离约 6 分钟后，一子级垂直返回，在海上“领航者号”回收\n船上通过网系捕获方式成功回收。此次任务是我国首次成功实施运载火箭一子级可控回收，同\n时也是全球首次运载火箭网系回收，标志着我国在重复使用火箭技术领域取得历史性突破。任\n务成功突破复杂力热环境适应性、高精度导航控制、海上平台网系捕获回收等关键核心技术，\n长征十号乙运载火箭成为我国首型成功实施回收的重复使用运载火箭，将为加快提升我国进出\n空间能力奠定坚实基础。","source":{"doc":"4e539a366dce19555ccf","first":29,"last":29,"page":29,"file":"2027年国省考时政热点考前大盘点.pdf"},"basis":"时政汇编"}]},"questions":{},"terms":{},"references":{},"topics":[{"slug":"innovation","title":"科技创新与科研组织"}],"units":{"k-47bdde1e2a61faad":[]}};
